278	    switched = pollButtons() || pollRotation();
279	    if (!switched) pollTouch();
280	    if (!switched && overlay_wants_redraw(&overlay, millis())) present();
281	  }
282	  if (!switched) waitUs += micros() - t2;
283	
284	  if (millis() - statsAt >= kStatsEveryMs) {
285	    printStats("run");
286	    resetStats();
287	  }
