  char buf[16];
  overlay_set_battery(&ov, 130);
  overlay_battery_text(&ov, buf, sizeof buf);
  TEST_ASSERT_EQUAL_STRING("100%", buf);
  overlay_set_battery(&ov, -5);
  overlay_battery_text(&ov, buf, sizeof buf);
